def run_length_encode(s: str) -> list:
    if not s:
        return []
    result = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            result.append((s[i - 1], count))
            count = 1
    result.append((s[-1], count))
    return result


@pytest.mark.parametrize(
    "input_string, expected",
    [
        ("aaabbc", [("a", 3), ("b", 2), ("c", 1)]),
        ("abc", [("a", 1), ("b", 1), ("c", 1)]),
        ("aaaa", [("a", 4)]),
        ("a", [("a", 1)]),
        ("aabbbaa", [("a", 2), ("b", 3), ("a", 2)]),
    ],
)
def test_run_length_encode_happy_path(input_string, expected):
    assert run_length_encode(input_string) == expected


def test_run_length_encode_empty_string():
    assert run_length_encode("") == []


def test_run_length_encode_preserves_case_sensitivity():
    assert run_length_encode("aaAAa") == [("a", 2), ("A", 2), ("a", 1)]


def test_run_length_encode_with_spaces():
    assert run_length_encode("aa  bb") == [("a", 2), (" ", 2), ("b", 2)]


def test_run_length_encode_with_punctuation():
    assert run_length_encode("!!!??.") == [("!", 3), ("?", 2), (".", 1)]


def test_run_length_encode_with_unicode_characters():
    assert run_length_encode("äääbb😊😊") == [("ä", 3), ("b", 2), ("😊", 2)]


def test_run_length_encode_with_newlines_and_tabs():
    assert run_length_encode("aa\n\n\t\tb") == [
        ("a", 2),
        ("\n", 2),
        ("\t", 2),
        ("b", 1),
    ]


def test_run_length_encode_long_run():
    assert run_length_encode("x" * 1000) == [("x", 1000)]


